        Assert.Equal(AtmStatus.Ok, machine.Execute(Account(0, 0), Deposit(0, 1, 0)).Status);
        Assert.Equal(AtmStatus.CassetteFull, machine.Execute(Account(0, 0), Deposit(0, 1, 0)).Status);
        Assert.Equal(Notes(0, 5, 0), dispenser.Stock);
    }

