using Atm;
int total = 0, explained = 0, other = 0;
foreach (Denomination? j in new Denomination?[]{null, Denomination.Fifty, Denomination.Twenty, Denomination.Ten})
for (int f=0;f<=5;f++) for (int t=0;t<=5;t++) for (int d=0;d<=5;d++)
for (int amount=10; amount<=200; amount+=10) {
  // solde et plafond larges : seul le stock compte ici
  var disp = new Rec(new NoteCounts(f,t,d), j);
  var r = new CashMachine(disp).Execute(new AccountState(250,0), new Operation.Withdraw(amount));
  if (r.Status == AtmStatus.DispenserFault) { total++; if (disp.First.Total > 4) explained++; else { other++; Console.WriteLine($"{f} {t} {d} {j} {amount} first={disp.First}"); } }
}
Console.WriteLine($"faults={total} explained(>4 au 1er passage)={explained} other={other}");
class Rec(NoteCounts s, Denomination? j) : IMoneyDispenser {
  readonly MoneyDispenser m = new(s, j); public NoteCounts First; bool seen;
  public NoteCounts Stock => m.Stock; public Denomination? Jammed => m.Jammed;
  public bool Dispense(NoteCounts n){ if(!seen){First=n;seen=true;} return m.Dispense(n);} public bool Load(NoteCounts n)=>m.Load(n);
}
EOF
